document.querySelectorAll('[data-lab="PM02-I1"]').forEach(root=>{const get=k=>root.querySelector('[data-field="'+k+'"]');const zh=(root.dataset.lang||root.closest('[data-lang]')?.dataset.lang)==='zh';const update=()=>{const c=+get('crystal').value/100,p=+get('pore').value/100,d=1/(c+(1-c)/.855),b=(1-p)*d;get('cvalue').textContent=(c*100).toFixed(0)+'%';get('pvalue').textContent=(p*100).toFixed(0)+'%';get('densebar').setAttribute('width',(d*550).toFixed(2));get('bulkbar').setAttribute('width',(b*550).toFixed(2));get('result').textContent=zh?'致密密度 '+d.toFixed(4)+' g/cm³；体密度 '+b.toFixed(4)+' g/cm³。增加结晶度使聚合物堆积更致密；增加孔隙则让相同聚合物质量占据更大总体积。图中两相密度固定为1.000与0.855 g/cm³。':'Dense-polymer density '+d.toFixed(4)+' g/cm³; bulk density '+b.toFixed(4)+' g/cm³. Increasing crystallinity makes polymer packing denser; adding pores gives the same polymer mass a larger total volume. Phase densities are fixed at 1.000 and 0.855 g/cm³.';};root.querySelectorAll('input').forEach(el=>el.addEventListener('input',update));update();});